/bin/zsh -lc "node --input-type=module <<'JS'
import {discountedTotal, splitCents} from './money.mjs';
import {overlaps, mergeWindows} from './windows.mjs';
console.log('discountedTotal(1000, 10):', discountedTotal(1000,10));
console.log('splitCents(10, 3):', JSON.stringify(splitCents(10,3)));
console.log('overlaps touching:', overlaps({start:0,end:1},{start:1,end:2}));
const input = [{start:1,end:3},{start:2,end:4}];
console.log('merge result:', JSON.stringify(mergeWindows(input)), 'input afterward:', JSON.stringify(input));
const singleton = [{start:1,end:2}];
console.log('returned singleton aliases input:', mergeWindows(singleton)[0] === singleton[0]);
JS"

